FILE source/database/003_web_permissions.sql
1: -- Trusted Web application database roles. Database-local rights only; no server login is created.
2: -- Viewer reads business data. Staff changes students and appends audit. Administrator adds master maintenance.
3: SET XACT_ABORT ON;
4: BEGIN TRANSACTION;
5: IF DB_NAME()<>'contextbase_test_project1_mvc' THROW 51205,N'Unexpected database for this project.',1;
6: IF DATABASE_PRINCIPAL_ID(N'student_viewer') IS NULL OR DATABASE_PRINCIPAL_ID(N'student_staff') IS NULL OR DATABASE_PRINCIPAL_ID(N'student_admin') IS NULL
7:  THROW 51214,N'Apply local 001_schema.sql before role grants.',1;
8: GRANT SELECT ON OBJECT::dbo.m_student TO student_viewer;
9: GRANT SELECT ON OBJECT::dbo.m_class TO student_viewer;
10: GRANT SELECT ON OBJECT::dbo.m_code_category TO student_viewer;
11: GRANT SELECT ON OBJECT::dbo.m_code TO student_viewer;
12: ALTER ROLE student_viewer ADD MEMBER student_staff;
13: ALTER ROLE student_staff ADD MEMBER student_admin;
14: GRANT INSERT,UPDATE ON OBJECT::dbo.m_student TO student_staff;
15: GRANT INSERT ON OBJECT::dbo.t_operation_log TO student_staff;
16: DENY DELETE ON OBJECT::dbo.m_student TO student_staff;
17: DENY UPDATE,DELETE ON OBJECT::dbo.t_operation_log TO student_staff;
18: GRANT INSERT,UPDATE ON OBJECT::dbo.m_class TO student_admin;
19: GRANT INSERT,UPDATE ON OBJECT::dbo.m_code TO student_admin;
20: DENY DELETE ON OBJECT::dbo.m_class TO student_admin;
21: DENY DELETE ON OBJECT::dbo.m_code TO student_admin;
22: DENY INSERT,UPDATE,DELETE ON OBJECT::dbo.m_code_category TO student_admin;
23: -- Current .NET Web contexts/confirmation tokens are server memory state; no t_confirmation/t_runtime_state DML is required.
24: -- MasterMaintenanceService independently checks IS_ROLEMEMBER('student_admin') on each connection.
25: COMMIT;
26: GO

